#[verifier::requires(true)]
#[verifier::ensures(
    // The returned boolean is true iff for every pair of indices i, j
    // in the vector, the entries at i and j are equal.
    ret == (forall |i: nat, j: nat|
                 i < arr@.len() && j < arr@.len() ==>
                 arr@[i] == arr@[j])
)]
#[verifier::decreases(arr.len())]
pub fn has_only_one_distinct_element(arr: &Vec<i32>) -> bool {
    // An empty array or a single-element array vacuously has only one distinct value.
    if let Some(&first) = arr.first() {
        // Check that every element equals the first one.
        arr.iter().all(|&x| x == first)
    } else {
        true
    }
}

